#pragma once
#include <atomic>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>
#include <cassert>

class Buffer {
public:
    explicit Buffer(std::size_t size = 1000) noexcept : buf_(size), read_pos_(0), write_pos_(0) {}
    explicit Buffer(std::span<const std::byte> bytes) noexcept : buf_(bytes.size()), read_pos_(0), write_pos_(bytes.size()) {
        std::copy(bytes.begin(), bytes.end(), buf_.begin());
    }
    explicit Buffer(std::initializer_list<std::byte> bytes) noexcept : buf_(bytes.size()), read_pos_(0), write_pos_(bytes.size()) {
        std::copy(bytes.begin(), bytes.end(), buf_.begin());
    }
    explicit Buffer(std::string_view str) noexcept : buf_(str.size()), read_pos_(0), write_pos_(str.size()) {
        std::copy(str.begin(), str.end(), reinterpret_cast<char*>(buf_.data()));
    }

    Buffer(const Buffer& other) noexcept = default;
    Buffer& operator=(const Buffer& other) noexcept = default;
    Buffer(Buffer&& other) noexcept = default;
    Buffer& operator=(Buffer&& other) noexcept = default;

    std::size_t WritableSize() const noexcept {
        return buf_.size() - (write_pos_ - read_pos_);
    }
    std::size_t ReadableSize() const noexcept {
        return write_pos_ - read_pos_;
    }
    bool Empty() const noexcept {
        return read_pos_ == write_pos_;
    }

    std::optional<std::byte> Peek() const noexcept {
        if (Empty()) return std::nullopt;
        return buf_[read_pos_];
    }
    std::span<const std::byte> ReadableBytes() const noexcept {
        return {buf_.data() + read_pos_, write_pos_ - read_pos_};
    }
    std::string ReadableString() const noexcept {
        return {reinterpret_cast<const char*>(ReadableBytes().data()), ReadableBytes().size()};
    }
    std::span<std::byte> WritableBytes() const noexcept {
        return {buf_.data() + write_pos_, buf_.size() - (write_pos_ - read_pos_)};
    }

    void Append(std::span<const std::byte> bytes) noexcept {
        EnsureWriteableSize(bytes.size());
        std::copy(bytes.begin(), bytes.end(), WriteIter());
        HasWritten(bytes.size());
    }
    void Append(std::initializer_list<std::byte> bytes) noexcept {
        Append({bytes.begin(), bytes.end()});
    }
    void Append(std::string_view str, std::optional<NewLine> new_line = std::nullopt) noexcept {
        EnsureWriteableSize(str.size());
        std::copy(str.begin(), str.end(), reinterpret_cast<char*>(WriteIter()));
        HasWritten(str.size());
    }
    void Append(const void* data, std::size_t size) noexcept {
        Append({static_cast<const std::byte*>(data), size});
    }
    void Append(const Buffer& buf) noexcept {
        Append(buf.ReadableBytes());
    }

    void EnsureWriteableSize(std::size_t size) noexcept {
        if (WritableSize() < size) MakeSpace(size);
    }
    void HasWritten(std::size_t size) noexcept {
        write_pos_ += size;
    }

    void Retrieve(std::size_t size) noexcept {
        assert(ReadableSize() >= size);
        read_pos_ += size;
    }
    std::size_t RetrieveUntil(const void* addr) noexcept {
        auto it = std::search(ReadIter(), WriteIter(), static_cast<const std::byte*>(addr), static_cast<const std::byte*>(addr) + 1);
        if (it == WriteIter()) return ReadableSize();
        std::size_t size = it - ReadIter();
        Retrieve(size);
        return size;
    }
    std::size_t RetrieveAll() noexcept {
        std::size_t size = ReadableSize();
        Retrieve(size);
        return size;
    }
    std::string RetrieveAllToString() noexcept {
        auto bytes = ReadableBytes();
        std::string str(reinterpret_cast<const char*>(bytes.data()), bytes.size());
        Retrieve(bytes.size());
        return str;
    }

    void Clear() noexcept {
        read_pos_ = 0;
        write_pos_ = 0;
    }

protected:
    std::size_t PrependableSize() const noexcept {
        return read_pos_;
    }
    void MakeSpace(std::size_t size) noexcept {
        if (PrependableSize() + WritableSize() >= size) {
            std::rotate(buf_.begin(), buf_.begin() + read_pos_, buf_.begin() + write_pos_);
            write_pos_ -= read_pos_;
            read_pos_ = 0;
        } else {
            buf_.resize(write_pos_ + size);
        }
    }

    std::vector<std::byte>::iterator ReadIter() const noexcept {
        return buf_.begin() + read_pos_;
    }
    std::vector<std::byte>::iterator WriteIter() const noexcept {
        return buf_.begin() + write_pos_;
    }

    std::vector<std::byte> buf_;
    std::atomic<std::size_t> read_pos_;
    std::atomic<std::size_t> write_pos_;
};

#pragma once
#include "Buffer.h"

class IOBuffer : public Buffer {
public:
    using Buffer::Buffer;

    std::size_t ReadFrom(io::IReadWriter& io) {
        EnsureWriteableSize(1024);
        auto bytes = WritableBytes();
        std::size_t read = io.Read(bytes.data(), bytes.size());
        HasWritten(read);
        return read;
    }

    std::size_t WriteTo(io::IReadWriter& io) {
        auto bytes = ReadableBytes();
        std::size_t written = io.Write(bytes.data(), bytes.size());
        Retrieve(written);
        return written;
    }
};
